import{_ as i,h as t,i as e,c as n,v as r,p as m,x as o,m as s,e as p,S as d}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"Llama 1 架构选择","description":"","frontmatter":{"title":"Llama 1 架构选择","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llama-1.md","filePath":"llm/llama-1.md","lastUpdated":1788454257000}'),h={name:"llm/llama-1.md"};function L(P,a,c,N,S,A){const l=t("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="llama-1-架构选择" tabindex="-1">Llama 1 架构选择 <a class="header-anchor" href="#llama-1-架构选择" aria-label="Permalink to &quot;Llama 1 架构选择&quot;">​</a></h1><div class="epigraph"><p>我们沿用 Transformer，并采纳随后提出的若干改进：Pre-normalization、SwiGLU、旋转位置编码；开源实现里线性层还不设偏置。</p><footer>—— 综合 Touvron et al., LLaMA, 2023 与公开实现</footer></div><p>2023 年 2 月，Touvron 等人发布 LLaMA（后称 Llama 1）：解码器-only 基础模型，尺寸 7B、13B、33B、65B，强调在公开数据上把密集 Transformer 训到与当时闭源大模型可比较的水平。它几乎没有发明新模块，而是把已经分开验证过的选择收成一套可复现配方：<a href="/llm/pre-ln-post-ln">Pre-LN</a> 用 <a href="/llm/rmsnorm">RMSNorm</a>、<a href="/llm/rope">RoPE</a>、<a href="/llm/swiglu">SwiGLU</a>，以及线性层无 bias。这套配方后来成为开源稠密模型的默认起点。本篇只写 Llama 1 的架构选择与它们为何被捆在一起，不进入对话对齐，也不把后续代际的上下文或混合专家写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2022 年底的公开模型要么小、要么数据与结构不透明。要在学术可引用的设定下回答「密集解码器在公开语料上能走多远」，必须先锁住一块计算图：残差怎么归一化、位置怎么进注意力、FFN 用什么激活、线性层有没有偏置。每一项当时都有文献，但组合并不唯一。Post-LN 的原版 Transformer、绝对位置、ReLU 或 GELU MLP、带 bias 的 GPT-2 风格投影，都可以训，只是深了之后稳不稳、同 FLOP 下困惑度好不好、推理内核好不好写，差一截。</p><p>Touvron 等人的问题不是再提一个注意力变体，而是选一条已经在 GPT-3、PaLM、GPT-Neo 上分别出现过的改进，用同一套超参训四个尺寸，并公开权重。架构选择因此是工程收敛：减少自由度，把差异留给数据与尺度。</p><h3 id="四项选择针对四个不同故障" tabindex="-1">四项选择针对四个不同故障 <a class="header-anchor" href="#四项选择针对四个不同故障" aria-label="Permalink to &quot;四项选择针对四个不同故障&quot;">​</a></h3><p>Pre-LN 针对深层梯度被残差后 LN 切断。<a href="/llm/rope">RoPE</a> 针对绝对位置在外推与相对几何上的弱点。SwiGLU 针对单支激活把「内容」与「门」绑死。无 bias 针对多一套加法参数带来的内核分支与训练噪声，并与 RMSNorm 的仿射共同管理尺度。四项不是互为替代，缺一项就会回到 2018–2020 年的某一种已知痛点。</p><p><span class="marginnote">论文正文点名的三项改动写着出处：Pre-normalization 来自 GPT-3 实践，RMSNorm 来自 Zhang 与 Sennrich 2019；SwiGLU 来自 Shazeer 2020 与 PaLM；RoPE 来自 Su 等 2021，论文写 GPT-Neo 用过。无 bias 是发布代码与随后复现里一致的默认，和这三项一起构成「LLaMA 块」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>块结构是 Pre-RMSNorm 的解码器层。子层 \\(F\\) 为因果多头注意力或 SwiGLU FFN：</p> \\[x \\leftarrow x + F\\bigl(\\mathrm{RMSNorm}(x)\\bigr). \\]<p>注意力仍是 <a href="/llm/mha">MHA</a>，不是分组查询。位置不把向量加到嵌入上，而在 \\(Q,K\\) 上施加 RoPE。FFN 为</p> \\[\\mathrm{SwiGLU}(x)=\\bigl(\\mathrm{SiLU}(xW) \\odot (xV)\\bigr)W_2, \\]<p>中间维取 \\(\\tfrac{2}{3}\\times 4d=\\tfrac{8}{3}d\\) 再按硬件对齐，使参数量与两层宽 \\(4d\\) 的 ReLU FFN 同量级。线性映射不设 \\(b\\)，包括注意力投影与 FFN；RMSNorm 保留缩放 \\(\\gamma\\)，出口再加一次归一化后接词预测头。词表约 32k，SentencePiece BPE。上下文长度 2048。7B/13B 约 1T token，33B/65B 约 1.4T。优化器 AdamW，\\(\\beta_2=0.95\\)，余弦衰减到峰值学习率的 10%。</p>',15)),(e(),m(d,null,{default:o(()=>[p(l,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%20x%22%5D%20--%3E%20N%5B%22RMSNorm%22%5D%0A%20%20N%20--%3E%20ATT%5B%22RoPE%20%E5%90%8E%E7%9A%84%E5%9B%A0%E6%9E%9C%20MHA%20%E6%97%A0%20bias%22%5D%0A%20%20ATT%20--%3E%20ADD1%5B%22%E5%8A%A0%E5%9B%9E%20x%22%5D%0A%20%20ADD1%20--%3E%20N2%5B%22RMSNorm%22%5D%0A%20%20N2%20--%3E%20FFN%5B%22SwiGLU%20%E6%97%A0%20bias%22%5D%0A%20%20FFN%20--%3E%20ADD2%5B%22%E5%8A%A0%E5%9B%9E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="无-bias-与-pre-ln-如何配合" tabindex="-1">无 bias 与 Pre-LN 如何配合 <a class="header-anchor" href="#无-bias-与-pre-ln-如何配合" aria-label="Permalink to &quot;无 bias 与 Pre-LN 如何配合&quot;">​</a></h3><p>带 bias 的线性层在 Pre-LN 里会给子层输出一个与输入无关的偏移，残差流的均值可以随层漂移，RMSNorm 又不减均值，偏移会累积。去掉 \\(b\\)，尺度主要交给 \\(\\gamma\\) 与残差本身，内核少一次加向量，张量并行切分更干净。这不是理论必需，而是与 RMSNorm、无 Dropout 的解码器一起出现的简洁化：能省的加法都省掉，让大矩阵乘占满时间。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Pre-LN 给残差一条不经过归一化的公路，65B、80 层量级才能用论文里的学习率起步。RMSNorm 比 LayerNorm 少一次减均值，带宽更省，LLaMA 把它写成默认，而不是再做一次「要不要中心化」的消融——消融已经在 RMSNorm 原文与 GPT-3 实践里做过。RoPE 让内积只含相对位移，2048 的训练长度下相对几何是稳的；更长外推不是 Llama 1 的设计目标，公式却为后来改基数留下了旋钮。</p><p>SwiGLU 在同参数下优于 GELU MLP，是 PaLM 已经付过的实验税。LLaMA 把中间维按 \\(\\tfrac{8}{3}\\) 对齐，避免「我们用了门控所以参数多 1.5 倍」这种不可比。无 bias 再减掉与 \\(d\\) 成正比的一小撮参数，四个尺寸的参数表更好对上「纯宽度 × 层数」的心算。</p><p><span class="marginnote">Llama 1 仍是满 KV 头的 MHA。服务期缓存按 \\(h_q\\) 计，70B 级尚未出现；当时的矛盾是训练吞吐与公开数据质量，不是 decode 带宽。把 GQA 提前写进 Llama 1 会错代。</span></p><h3 id="数据与架构哪一项在说话" tabindex="-1">数据与架构哪一项在说话 <a class="header-anchor" href="#数据与架构哪一项在说话" aria-label="Permalink to &quot;数据与架构哪一项在说话&quot;">​</a></h3><p>论文用公开混合语料（CommonCrawl、C4、书籍、维基、代码等）训到 1–1.4T token，并论证较小模型在足够 token 上可以追上更大而训不足的模型。架构配方的作用是：让这些 token 能稳定地变成深度。若换回 Post-LN 加绝对位置，同样数据也可能训崩或外推更差，于是人们会误判数据不行。把配方固定，后续工作才能把差异算在数据清洗、词表和对齐上。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Llama 1 的许可证与权重传播路径后来引发争议，那是发布策略问题，不是 Pre-LN 的数学问题。上下文 2048、MHA、32k 词表，都是 2023 年初的工作点：长文档、多语压缩、decode 缓存都还没成为这套权重的主约束。英文为主的数据配比会在非英语与代码上留下分词碎片，那是词表问题，留给数据与 tokenizer 专文，不是 RoPE 能修的。</p><p>没有 bias 并不禁止所有仿射：RMSNorm 的 \\(\\gamma\\) 还在。移植权重时若在 <code>nn.Linear</code> 里打开 bias，形状对不上检查点。从 GPT-2 式带 bias 模型蒸馏到 LLaMA 块，必须丢掉或吸收 \\(b\\)，不能当无成本。并行 Attention-FFN、Sandwich-LN、GQA 都不在 Llama 1 块内；它们是别的模型或后代的选择。</p><p><span class="marginnote">论文写 33B，社区常说 30B/32.5B，是因为公开配置与四舍五入。引用尺寸时跟 Touvron 等 2023 的表：7B、13B、33B、65B。不要把后代的 8B/70B 倒填进来。</span></p><p>训练稳定性仍依赖 warmup、梯度裁剪与数据清洗，Pre-LN 不是免责声明。65B 在 2048 张 80GB A100 上训约三周，说明配方再干净，尺度仍是集群问题。复现若只抄四项架构、用小数据，得不到论文表格，却仍能验证：块是稳的、无 bias 检查点能加载。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Llama 1 是公开数据上的密集解码器，架构收敛为 Pre-RMSNorm、RoPE、SwiGLU、线性无 bias。</li><li>注意力是因果 MHA，上下文 2048，词表约 32k SentencePiece。</li><li>SwiGLU 中间维按 \\(\\tfrac{8}{3}d\\) 对齐参数；RoPE 只转 \\(Q,K\\)。</li><li>四项选择分别稳住深度、相对位置、FFN 质量与内核简洁，而不是新注意力。</li><li>7B/13B 约 1T token，33B/65B 约 1.4T；配方为后续开源稠密模型提供默认块。</li><li>本篇不覆盖对话 SFT，也不覆盖更长上下文或 MoE。</li><li>出处：Touvron 等，<em>LLaMA: Open and Efficient Foundation Language Models</em>，2023。RMSNorm、RoPE、SwiGLU 分见 Zhang 与 Sennrich 2019，Su 等 2021，Shazeer 2020。</li></ul>',15))])}const B=i(h,[["render",L]]);export{E as __pageData,B as default};
